  inspector.innerHTML='<div class="film-inspector-head"><div><b>Revise o encaixe</b><small>Toque em uma arte para mover, girar ou travar.</small></div><button class="btn small" data-touch-move aria-pressed="false">Rolar / navegar</button><label>Fundo <select data-background aria-label="Fundo de visualização"><option value="check">Transparente</option><option value="white">Branco</option><option value="black">Preto</option><option value="gray">Cinza</option></select></label><label>Zoom <input data-zoom type="range" min="70" max="200" value="100" aria-label="Zoom do filme"></label></div><div class="film-selection-controls" hidden><span data-selected></span><label>X (cm)<input data-x inputmode="decimal"></label><label>Y (cm)<input data-y inputmode="decimal"></label><button class="btn small" data-position>Aplicar posição</button><button class="btn small" data-rotate>Girar</button><button class="btn small" data-lock>Travar</button></div><div class="film-inspector-foot"><span data-help aria-live="polite">O espaço mínimo entre artes é preservado. Arraste apenas pela própria arte.</span><button class="btn small" data-repack>Reotimizar livres</button></div>';
