  function updateSelection(){const p=placement(),controls=get('.film-selection-controls');controls.hidden=!p;if(!p)return;const size=sourceSize(p);get('[data-selected]').textContent=`${p.label} · ${cm(size.width)} × ${cm(size.height)} cm`;get('[data-x]').value=cm(p.xMm);get('[data-y]').value=cm(p.yMm);get('[data-lock]').textContent=p.locked?'Destravar':'Travar';get('[data-position]').disabled=busy||p.locked;get('[data-rotate]').disabled=busy||p.locked||!allowedRotations(p).length;get('[data-x]').disabled=get('[data-y]').disabled=busy||p.locked;get('[data-angle]').value=String(p.rotation||0).replace('.',',');get('[data-angle]').disabled=get('[data-apply-angle]').disabled=busy||p.locked||!layout.freeRotation||itemMap.get(p.id)?.rotationPolicy==='none';get('[data-angle-label]').hidden=get('[data-apply-angle]').hidden=!layout.freeRotation}
