const smooth=(start,end,value)=>{const t=Math.max(0,Math.min(1,(value-start)/(end-start)));return t*t*(3-2*t)};

// A disclosed derivative of the licensed oversized mesh, not a second scan.
// Continuous deformation leaves the collar/torso center untouched and reduces
// only the dropped-shoulder/distal sleeve region, preserving volumetric depth.
export function regularGarmentPoint(x,y,z,{bodyWidth,bodyLength}){
  const half=bodyWidth/2,q=Math.abs(x)/half,t=y/bodyLength+.5;
