}
// Optional preview refinement, preserving the lower-body calibration and depth.
// This is a disclosed artistic deformation, never a cloth-physics simulation.
export function relaxedGarmentPoint(x,y,z,{bodyWidth,bodyLength},model='oversized'){
  const q=Math.abs(x)/(bodyWidth/2),t=y/bodyLength+.5;
  const shoulder=smooth(.28,1.05,q)*smooth(.57,.89,t),drop=bodyLength*(model==='normal'?.073:.049)*shoulder;
