import {GARMENT_DEFAULTS,GARMENT_SIDES,SIDE_LABELS,garmentFrame,garmentAnchors,nearestGarmentAnchor,normalizeGarmentScene,layerOutsideSurface,renderGarmentView,renderGarmentPresentation} from './garment-scene.js?v=2.17.3';
import {createGarmentCloudStore} from './garment-cloud-store.js?v=2.17.3';
import {openStudioArtPicker} from './studio-art-picker.js?v=2.17.3';
import {assetPixelDimensions,createStudioPreviewCache} from './studio-art-preview.js?v=2.17.3';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dec=v=>Number(v).toLocaleString('pt-BR',{maximumFractionDigits:2,useGrouping:false});
const num=v=>Number(String(v).replace(',','.'));
const blobFor=canvas=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Não foi possível gerar a imagem.')),'image/png'));
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}

export async function openGarmentComposer(ctx,asset=null,options={}){
  const modal=document.createElement('div'),previous=document.activeElement,oldOverflow=document.body.style.overflow,controller=new AbortController();modal.className='art-studio-backdrop garment-composer-backdrop';
  modal.innerHTML=`<section class="art-studio garment-composer" role="dialog" aria-modal="true" aria-label="Montar camiseta completa"><header class="art-studio-head"><div><span class="studio-eyebrow">ZERO 19 / CAMISETA COMPLETA</span><h2>Uma peça. Todas as suas ideias.</h2><p>Frente, costas e mangas na mesma montagem.</p></div><button class="studio-close" aria-label="Fechar">×</button></header><div class="studio-loading">Preparando sua camiseta…</div><footer class="art-studio-footer"><span>Modelos fotográficos · medidas calibráveis</span></footer><div class="studio-message" aria-live="polite"></div></section>`;
  document.body.append(modal);document.body.style.overflow='hidden';const find=s=>modal.querySelector(s);let busy=false,dirty=false,observer=null,costPanel=null,closed=false,costTimer=null,cancelCostLayout=null;
  const previews=createStudioPreviewCache(ctx,{signal:controller.signal});
  const assertOpen=()=>{if(closed)throw new DOMException('Montagem fechada ou conta alterada.','AbortError')};
  const message=(text,error=false)=>{if(closed)return;find('.studio-message').textContent=text;find('.studio-message').classList.toggle('error',error)};
  const close=(force=false)=>{if(closed||busy&&!force)return;if(!force&&dirty&&!confirm('Fechar sem salvar a montagem? As medidas originais das artes não serão alteradas.'))return;closed=true;window.removeEventListener('z19:account-changing',accountChanging);controller.abort();clearTimeout(costTimer);cancelCostLayout?.();observer?.disconnect();costPanel?.destroy?.();modal.remove();document.body.style.overflow=force?'':oldOverflow;if(!force&&previous?.isConnected)previous.focus()};
  const accountChanging=()=>close(true);window.addEventListener('z19:account-changing',accountChanging);
  find('.studio-close').onclick=()=>close();modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();close()}if(e.key==='Tab'){const controls=[...modal.querySelectorAll('button,input,select,[tabindex="0"]')].filter(node=>!node.disabled&&node.getClientRects().length),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
  for(const type of ['click','input','change','pointerdown','keydown'])modal.addEventListener(type,event=>{if(busy){event.preventDefault();event.stopImmediatePropagation()}},true);
  const run=async(fn,label='Processando…')=>{if(busy||closed)return;busy=true;const controls=[...modal.querySelectorAll('button,input,select')].map(node=>[node,node.disabled]);controls.forEach(([node])=>node.disabled=true);message(label);try{await fn()}catch(error){if(error.name!=='AbortError')console.error(error);message(error.message||'A operação não foi concluída.',true)}finally{busy=false;for(const [node,disabled] of controls)if(node.isConnected)node.disabled=disabled}};
  try{
    let profile=null,image=null,localDraft=null,draftStore=null;
    if(asset){const profileResult=await ctx.supabase.from('z19p_asset_print_profiles').select('*').eq('asset_id',asset.id).maybeSingle();if(profileResult.error)throw profileResult.error;profile=profileResult.data;const dimensions=assetPixelDimensions(asset)||await previews.get(asset,{signal:controller.signal,pin:true});image={naturalWidth:dimensions.width,naturalHeight:dimensions.height}}
    else{draftStore=createGarmentCloudStore(ctx);if(options.draftId){localDraft=await draftStore.get(options.draftId);if(!localDraft)throw new Error('Montagem não encontrada. Volte ao estúdio e atualize a lista.')}}
    if(closed)return;
    let scene=normalizeGarmentScene(localDraft?.scene||asset?.metadata?.garment_scene||{title:asset?.name||'Minha camiseta'}),side=options.side||'front',selected=null,zoom=1,drag=null,quantity=1,garmentPrice=null;
    const assets=new Map(asset?[[asset.id,asset]]:[]),profiles=new Map(asset?[[asset.id,profile]]:[]);
    if(asset&&!scene.layers.length){if(options.placement){const p=options.placement;scene.color=p.color||scene.color;scene.measurements={bodyWidth:p.shirtWidth,bodyLength:p.shirtLength,sleeveWidth:p.sleeveWidth,sleeveLength:p.sleeveLength}}const f=garmentFrame(scene,side);scene.layers.push({id:crypto.randomUUID(),assetId:asset.id,name:asset.name,path:asset.processed_path||asset.original_path,side,width:Number(options.width||profile?.default_width_cm)||Math.min(28,image.naturalWidth/300*2.54),ratio:image.naturalWidth/image.naturalHeight,x:options.placement?.x??f.widthCm/2,y:options.placement?.y??f.lengthCm*.3,locked:false,halftone:Boolean(profile?.halftone)})}
    selected=scene.layers.find(layer=>layer.side===side)?.id||null;
    find('.studio-loading').outerHTML=`<div class="garment-layout"><div class="garment-visual"><div class="garment-toolbar"><div class="studio-segment">${GARMENT_SIDES.map(s=>`<button data-view="${s}">${SIDE_LABELS[s]}</button>`).join('')}</div><div class="garment-model-controls"><select id="garmentModel" aria-label="Modelo de camiseta"><option value="normal">Normal</option><option value="oversized">Oversized</option></select><div class="shirt-colors">${['black','white','offwhite'].map(color=>`<button data-garment-color="${color}" class="${color}" aria-label="${color==='black'?'Preta':color==='white'?'Branca':'Off-white'}"></button>`).join('')}</div></div></div><div class="garment-stage-viewport"><div class="garment-stage"><div class="garment-photo"></div><div class="garment-layers"></div></div></div><div class="shirt-visual-help"><span>Toque para escolher uma arte. Arraste pela borda laranja.</span><label>Zoom <input id="garmentZoom" type="range" min="100" max="180" value="100"></label></div><div class="garment-export-controls"><button class="studio-primary" id="garmentView3d">Ver em 3D</button><button class="studio-secondary" id="garmentShare3d">Link 3D para cliente</button><button class="studio-secondary" data-export="view">Baixar vista com artes</button><button class="studio-secondary" data-export="sheet">Ficha com as vistas usadas</button><button class="studio-secondary" data-export="blank">Baixar camiseta lisa</button><label class="studio-check"><input id="garmentAnnotations" type="checkbox" checked> Incluir medidas na imagem</label></div><p class="studio-note">Exportação em PNG, até 2.000 px por vista. A foto-base é ilustrativa; o ajuste em centímetros depende das medidas reais da sua peça. Estas vistas são 2D; use “Ver em 3D” para abrir o modelo interativo. Estes PNGs são apresentações ao cliente, não arquivos DTF para impressão em tamanho real.</p><div class="garment-cost-slot"></div></div><aside class="garment-settings"><label class="studio-field">Nome da montagem<input id="garmentTitle" value="${h(scene.title)}"></label><div class="garment-add-actions"><button class="studio-primary" id="garmentAddArt">＋ Adicionar outra arte</button><button class="studio-secondary" id="garmentRepeatArt">Repetir arte inicial</button></div><div class="garment-layer-list"></div><div class="garment-selection" hidden><span class="studio-eyebrow">ARTE SELECIONADA</span><h3 class="garment-selected-name"></h3><div class="shirt-dimensions"><label>Largura <span>cm</span><input id="garmentArtWidth" inputmode="decimal"></label><span>×</span><label>Altura <span>cm</span><input id="garmentArtHeight" inputmode="decimal"></label></div><div class="garment-layer-actions"><button class="studio-secondary" id="garmentLock">Fixar posição</button><button class="studio-secondary" id="garmentDuplicate">Duplicar</button><button class="studio-secondary" id="garmentRemove">Remover da peça</button></div><label class="studio-field">Posição universal<select id="garmentAnchor"></select></label><button class="studio-secondary" id="garmentSnap">Encaixar na posição mais próxima</button><button class="studio-secondary" id="garmentSaveSize">Salvar tamanho no cadastro desta arte</button><p class="studio-note">Mudar aqui não altera o arquivo nem a medida cadastrada até você usar o botão acima.</p><div class="garment-outside-note"></div></div><div class="studio-divider"></div><span class="studio-eyebrow">MEDIDAS REAIS DA PEÇA</span><div class="shirt-measure-fields">${[['bodyWidth','Largura do corpo'],['bodyLength','Ombro até a barra'],['sleeveWidth','Largura externa da manga'],['sleeveLength','Costura até a barra da manga']].map(([key,label])=>`<label>${label} (cm)<input data-measure="${key}" inputmode="decimal" value="${dec(scene.measurements[key])}"></label>`).join('')}</div><p class="studio-note">Mangas esquerda/direita de quem veste. Os pontos de encaixe são referências, não uma leitura automática da costura.</p><div class="garment-production-simulation"><div class="studio-divider"></div><span class="studio-eyebrow">SIMULAÇÃO DE PRODUÇÃO</span><label class="studio-field">Quantidade de camisetas<input id="garmentQuantity" type="number" min="1" max="999" value="1"></label><label class="studio-field">Custo de cada camiseta lisa (R$)<input id="garmentUnitCost" inputmode="decimal" placeholder="Opcional · preço de compra"></label><button class="studio-secondary" id="garmentCostButton">Calcular custo desta montagem</button></div></aside></div>`;
    find('.art-studio-footer').innerHTML='<div><b class="garment-summary"></b><small>Fixe quantas artes quiser em cada vista.</small></div><div><button class="studio-secondary" id="garmentShare">Apresentação para cliente</button><button class="studio-primary" id="garmentSave">Salvar montagem</button></div>';
    if(!asset){find('#garmentRepeatArt').remove();find('#garmentAddArt').textContent='＋ Escolher artes da biblioteca';find('#garmentSave').textContent=localDraft?.storage==='legacy-local'?'Transferir montagem para a nuvem':'Salvar montagem na nuvem';find('.art-studio-footer small').textContent='Disponível nos seus aparelhos depois de salvar na conta.';find('#garmentTitle').insertAdjacentHTML('afterend',`<small class="studio-note">${localDraft?.storage==='legacy-local'?'Rascunho antigo preservado. Salve para transferir à nuvem.':'Montagem independente na conta, sem alterar as artes originais.'}</small>`);}
    find('#garmentUnitCost').closest('label').insertAdjacentHTML('afterend','<p class="studio-note">Quantidade, custo da camiseta e largura do filme valem para esta simulação. A montagem salva guarda as artes, medidas e posições, não esses valores temporários.</p>');
    const stage=find('.garment-stage'),active=()=>scene.layers.find(layer=>layer.id===selected),scale=()=>stage.clientWidth*garmentFrame(scene,side).fraction/garmentFrame(scene,side).widthCm;
    const mark=()=>{dirty=true;costPanel?.invalidate?.();cancelCostLayout?.();clearTimeout(costTimer);costTimer=setTimeout(()=>{if(!closed)costPanel?.refresh?.()},500)};
    const previewRecord=layer=>assets.get(layer.assetId)||{path:layer.path};
    const previewImage=layer=>{const cached=previews.peek(layer.path);return `<img data-garment-preview="${h(layer.id)}" ${cached?`src="${h(cached.url)}"`:''} alt="${h(layer.name)}" draggable="false" decoding="async">`};
    function loadVisiblePreviews(){
      for(const layer of scene.layers.filter(layer=>layer.side===side)){
        const nodes=[...modal.querySelectorAll('[data-garment-preview]')].filter(node=>node.dataset.garmentPreview===layer.id);if(!nodes.some(node=>!node.getAttribute('src')))continue;
        previews.get(previewRecord(layer),{signal:controller.signal,pin:true}).then(preview=>{if(closed)return;for(const node of nodes)if(node.isConnected)node.src=preview.url;}).catch(error=>{if(closed||error.name==='AbortError')return;for(const node of nodes)if(node.isConnected){node.alt='Prévia indisponível';node.title='Não foi possível carregar a prévia. O arquivo original foi preservado.';}});
