      if(closed)return;const f=garmentFrame(scene,side);stage.style.aspectRatio=`1 / ${f.ratio}`;const viewport=find('.garment-stage-viewport'),maxHeight=parseFloat(getComputedStyle(viewport).maxHeight)||window.innerHeight*.6;stage.style.width=`${Math.min(viewport.clientWidth,maxHeight/f.ratio)*zoom}px`;const photo=find('.garment-photo');photo.style.backgroundImage=`url('${f.path}')`;photo.style.backgroundPosition=`${f.column*100}% ${f.row*100}%`;const s=scale();
      find('.garment-layers').innerHTML=scene.layers.filter(layer=>layer.side===side).map(layer=>`<div class="garment-art ${layer.id===selected?'selected':''} ${layer.locked?'locked':''}" data-layer="${h(layer.id)}" role="button" tabindex="0" aria-label="${h(layer.name)}" style="left:${f.left*stage.clientWidth+layer.x*s}px;top:${f.top*stage.clientHeight+layer.y*s}px;width:${layer.width*s}px;height:${layer.width/layer.ratio*s}px">${previewImage(layer)}${layer.id===selected?`<span>${dec(layer.width)} × ${dec(layer.width/layer.ratio)} cm</span>${layer.locked?'':'<button class="garment-resize" aria-label="Arrastar para redimensionar">↘</button>'}`:''}</div>`).join('');
      modal.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===side));modal.querySelectorAll('[data-garment-color]').forEach(b=>b.classList.toggle('active',b.dataset.garmentColor===scene.color));find('#garmentModel').value=scene.model;
      find('.garment-layer-list').innerHTML=`<div class="studio-eyebrow">${SIDE_LABELS[side].toUpperCase()}</div>${scene.layers.filter(layer=>layer.side===side).map(layer=>`<button class="garment-layer-row ${layer.id===selected?'active':''}" data-select-layer="${h(layer.id)}">${previewImage(layer)}<span>${h(layer.name)}<small>${dec(layer.width)} × ${dec(layer.width/layer.ratio)} cm ${layer.locked?'· fixada':''}</small></span></button>`).join('')||'<p class="studio-note">Nenhuma arte nesta vista. Adicione uma arte para começar.</p>'}`;
      const layer=active();find('.garment-selection').hidden=!layer||layer.side!==side;if(layer&&layer.side===side){find('.garment-selected-name').textContent=layer.name;if(sync){find('#garmentArtWidth').value=dec(layer.width);find('#garmentArtHeight').value=dec(layer.width/layer.ratio)}find('#garmentLock').textContent=layer.locked?'Desfixar posição':'Fixar posição';find('#garmentAnchor').innerHTML='<option value="">Escolher posição…</option>'+garmentAnchors(scene,side).map(anchor=>`<option value="${anchor.id}">${anchor.label}</option>`).join('');find('.garment-outside-note').textContent=layerOutsideSurface(scene,layer)?'Parte da arte está fora da superfície medida. Revise a posição antes de produzir.':'';for(const id of ['#garmentArtWidth','#garmentArtHeight','#garmentAnchor','#garmentSnap'])find(id).disabled=layer.locked}
      find('.garment-summary').textContent=`${scene.layers.length} estampa(s) · ${scene.model==='oversized'?'Oversized':'Normal'}`;
